// Keep the original selects as the form and application state; enhance their presentation.
const enhanced=new Map();let current=null,serial=0;
function enhance(select){
 if(select.id==='shipping-origin'||enhanced.has(select)||select.multiple||select.size>1)return;
 const wrap=document.createElement('div');wrap.className='pit-select';select.before(wrap);wrap.append(select);select.classList.add('pit-select-native');select.tabIndex=-1;select.setAttribute('aria-hidden','true');
 const trigger=document.createElement('button');trigger.type='button';trigger.className='pit-select-trigger';trigger.setAttribute('role','combobox');trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');
 const text=document.createElement('span'),chevron=document.createElement('span');chevron.className='pit-select-chevron';chevron.innerHTML='<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>';chevron.setAttribute('aria-hidden','true');trigger.append(text,chevron);wrap.append(trigger);
 const menu=document.createElement('div');menu.className='pit-select-menu';menu.id='pit-options-'+(++serial);menu.setAttribute('role','listbox');menu.setAttribute('popover','manual');wrap.append(menu);trigger.setAttribute('aria-controls',menu.id);
 let open=false,active=-1,signature='',search='',searchAt=0;
 const available=()=>[...select.options].map((o,i)=>!o.disabled&&!o.hidden?i:-1).filter(i=>i>=0);
 function close(){if(!open)return;open=false;if(menu.hidePopover)menu.hidePopover();else menu.hidden=true;trigger.setAttribute('aria-expanded','false');trigger.removeAttribute('aria-activedescendant');if(current===api)current=null;}
 function highlight(index){active=index;for(const row of menu.children)row.classList.toggle('is-active',Number(row.dataset.index)===active);const row=menu.querySelector('[data-index="'+active+'"]');if(row){trigger.setAttribute('aria-activedescendant',row.id);if(row.offsetTop<menu.scrollTop)menu.scrollTop=row.offsetTop;else if(row.offsetTop+row.offsetHeight>menu.scrollTop+menu.clientHeight)menu.scrollTop=row.offsetTop+row.offsetHeight-menu.clientHeight;}}
 function choose(i){if(select.options[i].disabled)return;select.selectedIndex=i;select.dispatchEvent(new Event('input',{bubbles:true}));select.dispatchEvent(new Event('change',{bubbles:true}));sync();close();trigger.focus();}
 function position(){const r=trigger.getBoundingClientRect(),height=window.visualViewport?.height||innerHeight,width=window.visualViewport?.width||innerWidth;menu.style.width=Math.min(Math.max(r.width,190),width-24)+'px';menu.style.left=Math.max(12,Math.min(r.left,width-parseFloat(menu.style.width)-12))+'px';const below=height-r.bottom-12,above=r.top-12,up=below<180&&above>below;menu.style.maxHeight=Math.max(80,Math.min(320,up?above:below))+'px';menu.style.top=(up?Math.max(12,r.top-Math.min(menu.scrollHeight,parseFloat(menu.style.maxHeight))-6):r.bottom+6)+'px';}
 function show(){if(trigger.disabled)return;current?.close();sync();open=true;current=api;if(menu.showPopover)menu.showPopover();else menu.hidden=false;trigger.setAttribute('aria-expanded','true');position();highlight(available().includes(select.selectedIndex)?select.selectedIndex:available()[0]);}
 function labelText(){const label=select.labels?.[0]?.cloneNode(true);label?.querySelectorAll('.pit-select,select').forEach(n=>n.remove());return label?.textContent.trim();}
 function sync(){trigger.disabled=select.disabled||!!select.closest('fieldset[disabled]');trigger.setAttribute('aria-label',select.getAttribute('aria-label')||labelText()||'Seleccionar opción');text.textContent=select.selectedOptions[0]?.textContent||'Seleccionar';trigger.setAttribute('aria-required',String(select.required));trigger.setAttribute('aria-invalid',String(!select.validity.valid&&trigger.dataset.validated==='true'));
 const next=JSON.stringify([...select.options].map(o=>[o.text,o.value,o.disabled,o.hidden,o.selected]));if(next!==signature){signature=next;menu.replaceChildren();[...select.options].forEach((o,i)=>{if(o.hidden)return;const row=document.createElement('div');row.id=menu.id+'-'+i;row.dataset.index=i;row.setAttribute('role','option');row.setAttribute('aria-selected',String(o.selected));row.setAttribute('aria-disabled',String(o.disabled));const icon=document.createElement('span');icon.className='pit-option-icon';icon.setAttribute('aria-hidden','true');if(select.id==='seller-presence'){icon.classList.add('state-dot',o.value);}else icon.textContent=o.selected?'✓':'–';const label=document.createElement('span');label.textContent=o.text;row.append(icon,label);row.onclick=()=>choose(i);menu.append(row);});if(open){position();highlight(select.selectedIndex);}}
 if(open&&(trigger.disabled||!trigger.checkVisibility()))close();}
 const api={close,sync,position};enhanced.set(select,api);trigger.onclick=()=>open?close():show();select.addEventListener('focus',()=>trigger.focus());select.addEventListener('invalid',e=>{e.preventDefault();trigger.dataset.validated='true';sync();show();trigger.focus();});select.addEventListener('change',sync);
 trigger.onkeydown=e=>{const list=available();if(['ArrowDown','ArrowUp','Home','End','Enter',' ','Escape'].includes(e.key)){e.preventDefault();if(e.key==='Escape'){close();return;}if(!open){show();return;}if(e.key==='Enter'||e.key===' '){if(active>=0)choose(active);return;}const at=list.indexOf(active);highlight(e.key==='Home'?list[0]:e.key==='End'?list.at(-1):list[Math.max(0,Math.min(list.length-1,at+(e.key==='ArrowDown'?1:-1)))]);}else if(e.key==='Tab')close();else if(e.key.length===1&&!e.ctrlKey&&!e.metaKey){search=Date.now()-searchAt>700?e.key:search+e.key;searchAt=Date.now();if(!open)show();const found=list.find(i=>select.options[i].text.toLocaleLowerCase().startsWith(search.toLocaleLowerCase()));if(found!==undefined)highlight(found);}};
 menu.addEventListener('toggle',e=>{if(e.newState==='closed'){open=false;trigger.setAttribute('aria-expanded','false');trigger.removeAttribute('aria-activedescendant');if(current===api)current=null;}});
 if(!menu.showPopover)menu.hidden=true;sync();
}
function scan(){document.querySelectorAll('select').forEach(enhance);}scan();new MutationObserver(scan).observe(document.body,{childList:true,subtree:true});
// Native value assignments and form.reset() do not emit change events.
setInterval(()=>{if(document.hidden)return;for(const [select,api]of enhanced){if(!select.isConnected){api.close();enhanced.delete(select);}else api.sync();}},250);
document.addEventListener('pointerdown',e=>{if(current&&!e.target.closest('.pit-select'))current.close();});window.addEventListener('resize',()=>current?.close());window.addEventListener('scroll',e=>{if(!e.target.closest?.('.pit-select-menu'))current?.position();},true);

document.addEventListener('keydown',e=>{if(e.key==='Escape')current?.close();});
